window.RP_SESSION={"id":"S-96524b99b7a6","messages":[{"id":"RP-0230913","time":"2026-08-16T04:16:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"설거지를 벅벅.","characters":["P-c93f55c91873"]},{"id":"RP-0230914","time":"2026-08-16T04:17:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-c93f55c91873"]},{"id":"RP-0230915","time":"2026-08-16T04:17:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 지능 판정 :\n[12] + [4] = [16]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0230916","time":"2026-08-16T04:21:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"재와 모래를 섞은 연마제를 기름기가 들러붙은 식기에 벅벅 문지른다.","characters":["P-c93f55c91873"]},{"id":"RP-0230917","time":"2026-08-16T04:27:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"마지막으로 뜨거운 물과 돼지기름으로 만든 비누로 뽀드득 소리가 나게 그릇을 닦고 나면 델타인도 기분이 좋아졌다.","characters":["P-c93f55c91873"]},{"id":"RP-0230918","time":"2026-08-16T04:37:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"남들이 깨끗이 비운 접시를 설거지통에 쏟아 넣고, 다시 연마제와 뜨거운 물, 그리고 비누나 행주로 벗겨내기. 처음 길드에 왔을 때는 애 좀 먹었지만, 이젠 익숙해진 작업이다.","characters":["P-c93f55c91873"]},{"id":"RP-0230920","time":"2026-08-16T04:38:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"하지만 여기서 잠깐! 델타인은 이따금 손가락으로 접시에 남은 양념을 찍어 맛보고 있었다. 이제 막 주방에 들어온 신입이 선배들의 맛을 배우는 전통적인 과정…….","characters":["P-c93f55c91873"]},{"id":"RP-0230921","time":"2026-08-16T04:39:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"……은 아니고, 가르쳐 달라고 해도 막상 배울 시간이 나지 않아 택한 방법이었다.","characters":["P-c93f55c91873"]},{"id":"RP-0230922","time":"2026-08-16T04:42:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그러다 깨끗한 물이 거의 다 떨어지자 다시 우물에서 물을 떠오고, 불을 떼워 끓여서 여분의 뜨거운 물을 만들고….","characters":["P-c93f55c91873"]},{"id":"RP-0230923","time":"2026-08-16T04:44:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그렇게 마지막 남은 상대는 커다란 솥과 냄비. 델타인은 손수 모래와 이파리, 깨끗한 천으로 솥 바닥을 벅벅 문질러…","characters":["P-c93f55c91873"]},{"id":"RP-0230924","time":"2026-08-16T04:44:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!어둠","characters":["P-c93f55c91873"]},{"id":"RP-0230925","time":"2026-08-16T04:44:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 어둠 판정 :\n[4, 5, 2] + [4, 1, 2]\n성공수 : [ 3 ]","characters":[]},{"id":"RP-0230926","time":"2026-08-16T04:45:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"거, 아무도 안 도와주는데 나 스스로 도움 좀 받을 수도 있지.","characters":["P-c93f55c91873"]},{"id":"RP-0230927","time":"2026-08-16T04:45:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인은 촉수 여섯 마리와 함께 빡빡빡….","characters":["P-c93f55c91873"]},{"id":"RP-0230928","time":"2026-08-16T04:48:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-c93f55c91873"]},{"id":"RP-0230929","time":"2026-08-16T04:48:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 지능 판정 :\n[5] + [4] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0230930","time":"2026-08-16T04:48:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"숙련된 손놀림, 아니, 촉수놀림으로 설거지를 끝마칠 수 있었다.","characters":["P-c93f55c91873"]},{"id":"RP-0230931","time":"2026-08-16T04:49:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그러기를 한 시간 즈음. 드디어 개수대에서 담갔다가 건진 마지막 냄비를, 마른 천으로 뽀드득 소리가 나게 닦을 수 있었다.","characters":["P-c93f55c91873"]},{"id":"RP-0230932","time":"2026-08-16T04:52:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"손의 물기를 털며 밖으로 후다닥 뛰쳐 나왔으나 이미 션과 아치타도 돌아가는 중! \n\n\"험, 내가 설거지를 너무 늦게까지 해버렸네.\"","characters":["P-c93f55c91873"]},{"id":"RP-0230933","time":"2026-08-16T04:53:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c93f55c91873"]},{"id":"RP-0230934","time":"2026-08-16T04:53:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
